# -*- coding: utf-8 -*-
"""料敵第二 — 日本語訳。"""

TITLE = '第二篇　料敵（りょうてき）'
HEAD = '''五段だが、全書で最も字数の多い篇である。第二段が一息に六国を片づけるからである。武侯の問いはきわめて具体的な難題から始まる。魏は四面を敵に囲まれている——秦は西を脅かし、楚は南を帯（めぐ）り、趙は北を衝き、斉は東に臨み、燕は後ろを絶ち、韓は前に拠る。「此を憂う、奈何せん」。

呉起の答えは陣法ではない。<b>六国の国民性の一覧表</b>である。斉人は性剛く国は富み、君臣は驕奢で細民を軽んじ、政は寛いが禄は均しからず、ゆえに陳は重くして堅からず。秦人は性強く、地は険しく政は厳しく賞罰は信あり、人は譲らず、ゆえに散じて自ら戦う。楚は弱く地は広く政は騒がしく民は疲れ、ゆえに整いて久しからず。燕は愨（まこと）で民は慎み、勇と義を好んで詐謀に乏しく、ゆえに守りて走らず。三晋は中国（中原）で性は和し政は平らかだが、民は戦いに疲れ将を軽んじ禄を薄しとし、ゆえに治まりて用いられず。性情の一つ一つに破り方が続く。中国の兵書で最も早い「敵情の性格表」であり、『孫子』と最も違うところでもある——孫子が算えるのは形と勢、呉起が算えるのは人である。

第三段は算え方を変える。<b>「卜わずして与に戦うべき者八」</b>と<b>「占わずして之を避くべき者六」</b>。八つはすべて敵の疲れ・渇き・長陣・尽きた資材・疫・倦み・軽さ・未定であり、六つはすべて敵の地の広さ・民の富み・上が下を愛すること・賞の信と刑の察・賢を任じ能を使うこと・大国の援けである。<b>占いを箇条書きに置き換える</b>——それがこの篇の骨である。末の二段はさらに細かく「十三の撃つべし」に至る。遠来して未だ定まらずから始まり、最後の一条は地形でも隊形でもなく、敵の心である。'''

PARA = {
 'p2-1': '武侯が呉起に言った、「いま秦はわが西を脅かし、楚はわが南を帯り、趙はわが北を衝き、斉はわが東に臨み、燕はわが後を絶ち、韓はわが前に拠っている。六国の兵が四方を守っており、形勢ははなはだ不便である。これを憂えている、どうすればよいか」。（「帯る」は帯のように取り巻くこと。「衝く」は要衝に当たること。魏は都を安邑に、のち大梁に置いたが、いずれも天下の中央で四面みな敵——これが魏の地理上の宿命であり、のちに強国から転落した理由でもある。武侯は文侯の子、名は撃。四庫本は「六国之兵四守」と、助字を一つ多く作る。）',
 'p2-2': '''呉起が答えた、「およそ国家を安んずる道は、先んじて戒めることを宝とします。いま君はすでに戒めておられる、禍いは遠のきましょう。臣に六国の俗を論じさせてください。斉の陳は重くして堅からず、秦の陳は散じて自ら闘い、楚の陳は整いて久しからず、燕の陳は守りて走らず、三晋の陳は治まりて用いられません。斉は性剛く、その国は富み、君臣は驕奢で細民を簡（あなど）り、その政は寛いが禄は均しくなく、一つの陳に二つの心があり、前は重く後は軽い。ゆえに重くして堅からず。これを撃つ道は、必ずこれを三分し、その左右を猟（か）り、脅してこれを従わせれば、その陳は壊すことができます。秦は性強く、その地は険しく、その政は厳しく、その賞罰は信あり、その人は譲らず、みな闘心がある。ゆえに散じて自ら戦う。これを撃つ道は、必ずまずこれに利を示して引き去らせ、士が得るに貪って将を離れたところで、乖（そむ）きに乗じ散じたるを猟り、伏を設け機に投ずれば、その将は取ることができます。楚は性弱く、その地は広く、その政は騒がしく、その民は疲れている。ゆえに整いて久しからず。これを撃つ道は、その屯を襲い乱し、まずその気を奪い、軽く進み速く退き、弊れさせ労れさせて、与に争い戦わなければ、その軍は敗ることができます。燕は性愨（まこと）で、その民は慎み、勇と義を好み、詐謀に寡ない。ゆえに守りて走らず。これを撃つ道は、触れて迫り、凌いで遠ざかり、馳せてその後に出れば、上は疑い下は懼れます。わが車騎をその必ず避くべき路に謹んで置けば、その将は虜にすることができます。三晋は中国（中原）であり、その性は和し、その政は平らかで、その民は戦いに疲れ、兵に習い、その将を軽んじ、その禄を薄しとし、士に死志がない。ゆえに治まりて用いられず。これを撃つ道は、険を阻んでこれを圧し、衆来れば拒み、去れば追い、以てその師を倦ませることです。これがその勢いであります。しかしながら一軍のうちには必ず虎賁の士がおります。力は鼎を扛（あ）げるに軽く、足は戎馬より軽く、旗を搴（ぬ）き将を取る、必ず能くする者がある。この等の者は選び別けて、愛し貴ぶべきです——これを『軍命』といいます。そのうち五兵を工（たくみ）に用い、材力健やかに疾く、志が敵を呑むにある者には、必ずその爵列を加えれば、以て勝を決することができます。その父母妻子を厚くし、賞を勧め罰を畏れさせれば、これは堅陳の士、与に久しきを持すべき者となります。よくこれを料ることができれば、倍する敵を撃つことができます」。武侯が言った、「善し」。（「愨」は素朴・実直。「乖に乗じ散じたるを猟る」は離心して散らばったところを狩ること。「軍命」は一軍の命脈のかかるところ。「五兵」は戈・殳・戟・酋矛・夷矛、転じて兵器一般。「倍を撃つ」は一を以て二に当たること。六国それぞれに一つの性情と一つの破り方があり、破り方はことごとく性情から生えている——斉は富んで驕るから分けて擾し、秦人は得るに貪るから利で誘い、楚は政が騒がしいから引き延ばし、燕は走らないから背後に回り、三晋は死志がないから消耗させる。二本はともに「搴旗斬将」に作り、底本は「取将」。また二本はともに「能審料此」に作り、底本は「審能料此」。いずれも底本は通ずるので旧に従い、ここに記す。四庫本は「今君已戒」を「今君先戒」、「可与持久」を「可以持久」に作る。叢刊本は「其民慎」を「其氏慎」に作る、形訛。）''',
 'p2-3': '呉子が言った、「およそ敵を料るに、卜わずして与に戦うべき者が八つある。一は、疾風大寒に、早く興きて寤（さ）めるや遷り、氷を剖（わ）って水を済（わた）り、艱難を憚らぬとき。二は、盛夏炎熱に、晏（おそ）く興きて間（やす）むことなく、行き驅けて飢え渇き、遠くを取ることに務めるとき。三は、師すでに淹（ひさ）しく、糧食が無く、百姓は怨り怒り、祅祥（妖しい前兆）がしばしば起こって、上がこれを止められぬとき。四は、軍資すでに竭き、薪芻すでに寡なく、天は陰雨多く、掠めようにも掠める所の無いとき。五は、徒衆多からず、水地は利あらず、人馬に疾疫あり、四隣の援けが至らぬとき。六は、道遠く日暮れ、士衆は労れ懼れ、倦れて未だ食わず、甲を解いて息（やす）んでいるとき。七は、将は薄く吏は軽く、士卒は固からず、三軍しばしば驚き、師徒に助けの無いとき。八は、陳して未だ定まらず、舎して未だ畢らず、阪を行き険を渉って、半ばは隠れ半ばは出ているとき。かくのごとき者は、これを撃って疑うな。占わずしてこれを避くべき者が六つある。一は、土地広大にして人民富み衆きとき。二は、上がその下を愛し、恵みの施しが流れ布いているとき。三は、賞に信あり刑は察く、発すれば必ず時を得ているとき。四は、功を陳ねて列に居らしめ、賢を任じ能を使っているとき。五は、師徒の衆きと兵甲の精いとき。六は、四隣の助けと大国の援けのあるとき。およそこれらが敵人に如かぬならば、これを避けて疑うな。これがいわゆる『可を見て進み、難を知りて退く』である」。（「寤遷」は目覚めるや陣を払うこと。「祅祥」は妖祥、異常な前触れ。「薪芻」は薪と馬糧。八条はすべて敵の疲・渇・久・竭・疫・倦・軽・未定という敵自身の身の上に落ち、六条はすべて敵の国政に落ちる。前の八つは今この時の狼狽、後の六つは平生の底力であり、底力の厚い相手は一時の狼狽に乗じてはならぬ。「不卜」「不占」の四字がこの段の眼——呉起は占いを、数えられる箇条に置き換えようとしている。叢刊本は「剖冰済水」を「刋木済水」に作る。）',
 'p2-4': '武侯が問うた、「わたしは敵の外を観てその内を知り、その進むを察してその止まるを知り、以て勝負を定めたい。聞かせてもらえるか」。呉起が答えた、「敵人の来ること、蕩蕩として慮りがなく、旌旗は煩乱し、人馬がしばしば顧みるようなら、一を以て十を撃つことができ、必ずこれに措く（手を打つ）いとまを与えぬようにします。諸侯が未だ会せず、君臣が未だ和せず、溝壘が未だ成らず、禁令が未だ施されず、三軍が匈匈と騒がしく、前へ出ようとしてできず、去ろうとして敢えてできぬようなら、半ばを以て倍を撃って、百戦して殆うくありません」。（「蕩蕩として慮りなし」は散漫で謀りがないこと。「匈匈」は「洶洶」に同じ、喧しい音。四庫本は「洶洶」に作る。「しばしば顧みる」——士卒が振り返って見ているのは退路である。一軍が撃つべきか否かは、首がどちらを向いているかで分かる。前段は敵の置かれた境遇を数え、この段は敵の見た目を見る。いずれも占いを俟たない。叢刊本は「諸侯未会」を「諸侯大会」に作る。）',
 'p2-5': '武侯が、敵を必ず撃つべき機について問うた。呉起が答えた、「兵を用いるには必ず敵の虚実を審らかにして、その危うい所へ趨るのです。敵人が遠来して新たに至り、行列が未だ定まらぬとき、撃つべし。すでに食べて未だ備えを設けぬとき、撃つべし。奔り走っているとき、撃つべし。勤め労れているとき、撃つべし。地の利を得ていないとき、撃つべし。時を失って従（つらな）っていないとき、撃つべし。長き道を渉り、後行が未だ息わぬとき、撃つべし。水を渉って半ば渡ったとき、撃つべし。険しい道、狭い路にあるとき、撃つべし。旌旗が乱れ動くとき、撃つべし。陳がしばしば移り動くとき、撃つべし。将が士卒を離れたとき、撃つべし。心が怖れているとき、撃つべし。およそかくのごとき者は、鋭を選んでこれに衝（あ）て、兵を分けてこれに継ぎ、急ぎ撃って疑うな」。（「時を失して従わず」は時刻を誤って部伍が相従っていないこと。「鋭を選んで衝て、兵を分けて継ぐ」は前後二段の手——まず突破口、次に増援。十三条は外から内へ進む。行列・飲食・足取り、次に地形・時機・渡河、そして最後の「心怖、撃つべし」はもはや隊形ではなく人の心である。『孫子』の「三軍は気を奪うべく、将軍は心を奪うべし」と同じ筋。二本はともに「用兵必須審敵虚実」に作り、底本は「須」を欠くが義は同じ、底本に従う。叢刊本は「旌旗乱動、撃つべし」の一条を「渉長道」の前に置き、次序が底本・四庫本と異なる。）',
}
